// TestCometBFTLightBlockValidateSetChanged covers the one behaviour Hertz changes: the
// trusted consensus state here holds two of the block's three validators, so the set did
// change, and only the Hertz contract reports it.
func TestCometBFTLightBlockValidateSetChanged(t *testing.T) {
	inputStr := ""

	input, err := hex.DecodeString(inputStr)
	require.NoError(t, err)

	beforeHertz, err := (&cometBFTLightBlockValidate{}).Run(input)
	require.NoError(t, err)
	afterHertz, err := (&cometBFTLightBlockValidateHertz{}).Run(input)
	require.NoError(t, err)

	require.Equal(t, byte(0x00), beforeHertz[0])
	require.Equal(t, byte(0x01), afterHertz[0])
	require.Equal(t, beforeHertz[1:], afterHertz[1:])
}

